"""Original MIT test-only Z80 fixtures for Issues #41/#47/#49/#53/#57/#59/#61/#69; no external ROM/code inputs.
Run python3 tests/fixtures/philips.py to regenerate the sparse hex images.
The system probes slot 1, MSX2 sub-ROM/RAM, then slot 2's AB init vector.
"""
from pathlib import Path

class Z80:
    def __init__(self, base):
        self.base, self.code, self.labels, self.fixups = base, [], {}, []
    def emit(self, *data):
        self.code.extend(data)
    def label(self, name):
        self.labels[name] = self.base + len(self.code)
    def jump(self, opcode, label):
        self.emit(opcode, 0, 0)
        self.fixups.append((len(self.code)-2, label))
    def done(self):
        for offset, label in self.fixups:
            address = self.labels[label]
            self.code[offset:offset+2] = [address & 255, address >> 8]
        return self.code

def save(name, spans):
    lines = ['# Original MIT Z80 fixture. Generated by philips.py. Offsets are file offsets.']
    for offset, data in spans:
        for i in range(0, len(data), 16):
            lines.append(f'{offset+i:04x}: ' + ' '.join(f'{x:02x}' for x in data[i:i+16]))
    Path(__file__).with_name(name+'.hex').write_text('\n'.join(lines)+'\n')

def wait_complete(code, label, register=0x7ff8):
    # Completion belongs to the serializer/CRC tail, not the final CPU service.
    code.label(label)
    code.emit(0x3a, register & 255, register >> 8, 0xe6, 1)
    code.jump(0xc2, label)

# System starts with page 0/1 BIOS and page 2/3 RAM. Initialize the expanded
# slot and mapper on MSX2 (ordinary writes/unused ports are harmless on MSX1).
s = Z80(0x100)
s.emit(0xf3, 0x3e, 0xfc, 0x32, 0xff, 0xff, 0x3e, 1, 0xd3, 0xfe,
       0x3e, 2, 0xd3, 0xff, 0x31, 0, 0xf0)
# Probe parked ASCII8SRAM2 cartridge through normal slot mapping.
s.emit(0x3e, 0xd4, 0xd3, 0xa8, 0x3a, 0, 0x40, 0x32, 0x10, 0xc0,
       0x3e, 0x20, 0x32, 0, 0x70, 0x3e, 0x6d, 0x32, 0x23, 0x81,
       0x3e, 0xf0, 0xd3, 0xa8)
# Copy a sub-ROM probe to RAM so page 0 can be switched safely.
s.emit(0x21, 0, 3, 0x11, 0, 0xc1, 0x01, 17, 0, 0xed, 0xb0, 0xcd, 0, 0xc1)
# Discover AB and call its vector with the real CPU, no host BIOS service.
s.emit(0x3e, 0xf8, 0xd3, 0xa8, 0x3a, 0, 0x40, 0xfe, ord('A'))
s.jump(0xc2, 'fail')
s.emit(0x3a, 1, 0x40, 0xfe, ord('B'))
s.jump(0xc2, 'fail')
s.emit(0x2a, 2, 0x40, 0x11, 0x80, 1, 0xd5, 0xe9) # vector returns at 0180
s.label('fail'); s.emit(0x76); s.jump(0xc3, 'fail')
trampoline = [0x3e, 0xf3, 0xd3, 0xa8, 0x3a, 0, 1, 0x32, 0x11, 0xc0,
              0x3e, 0xf0, 0xd3, 0xa8, 0xc9, 0, 0]
save('philips-system', [(0, [0xc3, 0, 1]), (0x100, s.done()),
                         (0x180, [0x76, 0x18, 0xfd]), (0x300, trampoline)])

# Disk ROM init reads sector 1 directly into page-2 RAM and executes it.
r = Z80(0x4100)
r.emit(0x3e, 0x80, 0x32, 0xfd, 0x7f, 0xaf, 0x32, 0xfc, 0x7f,
       0x32, 0xf9, 0x7f, 0x3e, 1, 0x32, 0xfa, 0x7f,
       0x3e, 0x80, 0x32, 0xf8, 0x7f, 0x21, 0, 0x80, 0x01, 0, 2)
# This 65535-iteration signal poll allows >5M cycles, exceeding the Type-II
# bound of 30 ms + five revolutions (3686931.35 cycles), including MSX waits.
r.emit(0x11, 0xff, 0xff)
r.label('poll'); r.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); r.jump(0xca, 'data')
r.emit(0xcb, 0x77); r.jump(0xca, 'fail')
r.emit(0x1b, 0x7a, 0xb3); r.jump(0xc2, 'poll'); r.jump(0xc3, 'fail')
r.label('byte'); r.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); r.jump(0xc2, 'byte')
r.label('data'); r.emit(0x3a, 0xfb, 0x7f, 0x77, 0x23, 0x0b, 0x78, 0xb1); r.jump(0xc2, 'byte')
wait_complete(r, 'complete')
r.emit(0x3a, 0xf8, 0x7f, 0xe6, 0xfc); r.jump(0xc2, 'fail'); r.emit(0xc3, 0, 0x80)
r.label('fail'); r.emit(0x3e, 0xee, 0x32, 0, 0xc0, 0x76); r.jump(0xc3, 'fail')
save('philips-disk', [(0, [ord('A'), ord('B'), 0, 0x41]), (0x100, r.done())])

# Sector code paints a green backdrop (real VDP output) and writes 512 A6 bytes
# to sector 9 on the side in 81F1, polling active-low IRQ/DRQ. Mode byte 81F0 selects force interrupt
# after the first byte (1) or later underrun (2); default is a complete write.
p = Z80(0x8000)
p.emit(0x3e, 0xa5, 0x32, 0, 0xc0,
       0x3e, 0, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
       0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99,
       0x3e, 0xf2, 0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
       0x3a, 0xf1, 0x81, 0x32, 0xfc, 0x7f,
       0x3e, 9, 0x32, 0xfa, 0x7f, 0x3e, 0xa0, 0x32, 0xf8, 0x7f,
       0x01, 0, 2)
p.label('byte'); p.emit(0x11, 0xff, 0xff)
p.label('poll'); p.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); p.jump(0xca, 'data')
p.emit(0xcb, 0x77); p.jump(0xca, 'done')
p.emit(0x1b, 0x7a, 0xb3); p.jump(0xc2, 'poll')
p.emit(0x3e, 0xfe); p.jump(0xc3, 'record')
p.label('data'); p.emit(0x3e, 0xa6, 0x32, 0xfb, 0x7f,
                        0x3a, 0xf0, 0x81, 0xfe, 1); p.jump(0xca, 'abort')
p.emit(0xfe, 2); p.jump(0xca, 'underrun')
p.emit(0x0b)
p.label('fast_byte'); p.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); p.jump(0xc2, 'fast_byte')
p.emit(0x3e, 0xa6, 0x32, 0xfb, 0x7f, 0x0b, 0x78, 0xb1); p.jump(0xc2, 'fast_byte')
p.jump(0xc3, 'done')
p.label('abort'); p.emit(0x3e, 0xd8, 0x32, 0xf8, 0x7f); p.jump(0xc3, 'done')
p.label('underrun'); p.emit(0x11, 0xff, 0xff)
p.label('delay'); p.emit(0x1b, 0x7a, 0xb3); p.jump(0xc2, 'delay')
p.label('done'); wait_complete(p, 'complete'); p.emit(0x3a, 0xf8, 0x7f)
p.label('record'); p.emit(0x32, 1, 0xc0, 0x3e, 0x5a, 0x32, 2, 0xc0)
p.label('halt'); p.emit(0x76); p.jump(0xc3, 'halt')
save('philips-sector', [(0, p.done()), (0x1f0, [0, 0])])

# Issue #47 movement probe, executed as a sector through the same AB disk ROM.
# All instructions and trace expectations are original. Seek 0 -> 5 at 6 ms,
# observe Track 2 with BUSY, force interrupt, wait beyond the original seek,
# then read track 2 / sector 1 and write a trace to track 2 / sector 9.
q = Z80(0x8000)
def load(address):
    q.emit(0x3a, address & 255, address >> 8)
def store(address):
    q.emit(0x32, address & 255, address >> 8)
def value(address, byte):
    q.emit(0x3e, byte); store(address)
def check(byte, mask=255):
    if mask != 255:
        q.emit(0xe6, mask)
    q.emit(0xfe, byte); q.jump(0xc2, 'fail')
def record(address, register, expected, mask=255):
    load(register); store(address); check(expected, mask)

value(0x7ffb, 5); value(0x7ff8, 0x10)
q.emit(0x11, 0xff, 0xff)
q.label('moving'); load(0x7ff9); q.emit(0xfe, 2); q.jump(0xca, 'progress')
q.jump(0xd2, 'fail') # A > 2 means intermediate motion was skipped.
q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'moving'); q.jump(0xc3, 'fail')
q.label('progress')
record(0x9000, 0x7ff9, 2)
record(0x9001, 0x7ff8, 1, 0x11) # BUSY, no seek error.
record(0x9002, 0x7fff, 0xff) # Active-low IRQ and DRQ both inactive.
value(0x7ff8, 0xd8)
record(0x9003, 0x7ff9, 2)
record(0x9004, 0x7fff, 0xbf) # Immediate IRQ, no DRQ.
record(0x9005, 0x7ff8, 0, 0x11) # Not BUSY; D8 remains latched.
record(0x9006, 0x7fff, 0xbf)
value(0x7ff8, 0xd0) # Explicitly release immediate IRQ.
q.emit(0x11, 0xff, 0xff)
q.label('delay'); q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'delay')
record(0x9007, 0x7ff9, 2) # Future pulses must remain canceled.
value(0x7ffa, 1); value(0x7ff8, 0x80)
q.emit(0x21, 0x00, 0x92, 0x01, 0, 2)
q.label('read_byte'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'read_byte')
q.label('read_data'); load(0x7ffb); check(0x62)
q.emit(0x77, 0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'read_byte')
wait_complete(q, 'complete'+str(len(q.code)))
load(0x7ff8); check(0, 0xfd)
# Copy eight observations over the first eight bytes of the read buffer.
q.emit(0x21, 0, 0x90, 0x11, 0, 0x92, 0x01, 8, 0, 0xed, 0xb0)
value(0x7ffa, 9); value(0x7ff8, 0xa0)
q.emit(0x21, 0, 0x92, 0x01, 0, 2)
q.label('write_byte'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'write_byte')
q.label('write_data'); q.emit(0x7e); store(0x7ffb)
q.emit(0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'write_byte')
wait_complete(q, 'complete'+str(len(q.code)))
load(0x7ff8); check(0, 0xfd)
q.emit(0x3e, 0xa5); store(0xc020)
q.emit(0x3e, 0xf2); q.jump(0xc3, 'paint') # Green success, red failure.
q.label('fail'); q.emit(0x3e, 0xee); store(0xc020); q.emit(0x3e, 0xf6)
q.label('paint'); q.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
    0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
    0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
q.label('halt'); q.emit(0x76); q.jump(0xc3, 'halt')
movement = q.done()
assert len(movement) <= 510
save('philips-movement', [(0, movement)])

# Issue #49: sector -> accessory RAM -> real CPU SCC-I accesses. The selected
# profile's first populated bank is supplied at sector offset 1FE (0 or 8).
# Slot 2's disk ROM and the system/sub-ROM probes above are reused unchanged.
a = Z80(0x4800)
def av(address, byte):
    a.emit(0x3e, byte, 0x32, address & 255, address >> 8)
def trace(source, target):
    a.emit(0x3a, source & 255, source >> 8, 0x32, target & 255, target >> 8)
a.emit(0x3e, 0xd4, 0xd3, 0xa8) # code in accessory page 1 can expose page 2
av(0x4123, 0x6d); trace(0x4123, 0xc032)
av(0xbffe, 0); av(0x9000, 0x3f)
a.emit(0x3e, 0xd4, 0xd3, 0xa8) # accessory in pages 1/2, CPU stays at 4800
# Compatible wave 4 writes update fifth readback.
av(0x9860, 0x44); trace(0x98a0, 0xc030)
av(0x9886, 99); av(0x9887, 0); av(0x988d, 15); av(0x988f, 8)
# Switch to plus: independent constant +64 wave 4 and +/-96 square wave 5.
av(0xbffe, 0x20); av(0xb000, 0x80)
a.emit(0x21, 0x60, 0xb8, 0x06, 32, 0x3e, 64)
a.label('wave4'); a.emit(0x77, 0x23, 0x05); a.jump(0xc2, 'wave4')
a.emit(0x21, 0x80, 0xb8, 0x06, 16, 0x3e, 96)
a.label('positive'); a.emit(0x77, 0x23, 0x05); a.jump(0xc2, 'positive')
a.emit(0x06, 16, 0x3e, 160)
a.label('negative'); a.emit(0x77, 0x23, 0x05); a.jump(0xc2, 'negative')
trace(0xb880, 0xc031)
av(0xb8a8, 199); av(0xb8a9, 0); av(0xb8ae, 15); av(0xb8af, 16)
# Return to sector RAM, leave the sound overlay hidden by slot selection.
a.emit(0x3e, 0xf4, 0xd3, 0xa8, 0xc9)
accessory = a.done()
assert len(accessory) < 254
b = Z80(0xc200)
b.emit(0x3e, 0xf4, 0xd3, 0xa8, 0x3a, 0xfe, 0x81, 0x32, 0, 0x50,
       0x3e, 0xd4, 0xd3, 0xa8, 0x3e, 1, 0x32, 0xfe, 0xbf,
       0x3e, 0xf4, 0xd3, 0xa8, 0x21, 0, 0x81, 0x11, 0, 0x48, 0x01, len(accessory), 0, 0xed, 0xb0,
       0xcd, 0, 0x48)
for address, expected in [(0xc030,0x44),(0xc031,96),(0xc032,0x6d)]:
    b.emit(0x3a, address & 255, address >> 8, 0xfe, expected); b.jump(0xc2,'fail')
# Write a full sector of 6C through the retained Philips interface. Page 3 code
# remains visible while page 1 switches back to slot 2.
b.emit(0x3e,0xf8,0xd3,0xa8,0x3e,9,0x32,0xfa,0x7f,
       0x3e,0xa0,0x32,0xf8,0x7f,0x01,0,2)
b.label('write_poll'); b.emit(0x3a,0xff,0x7f,0xcb,0x7f); b.jump(0xc2,'write_poll')
b.emit(0x3e,0x6c,0x32,0xfb,0x7f,0x0b,0x78,0xb1); b.jump(0xc2,'write_poll')
wait_complete(b, 'complete')
b.emit(0x3a,0xf8,0x7f,0xe6,0xfd); b.jump(0xc2,'fail')
b.emit(0x3e,0xa5,0x32,0x33,0xc0,0x3e,0xf2); b.jump(0xc3,'paint')
b.label('fail'); b.emit(0x3e,0xee,0x32,0x33,0xc0,0x3e,0xf6)
b.label('paint'); b.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
       0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
       0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
b.label('halt'); b.emit(0x76); b.jump(0xc3, 'halt')
boot = b.done()
assert len(boot) < 192
# Run the slot-changing bootstrap in page 3, copied by ordinary LDIR.
entry = [0x21,0x40,0x80,0x11,0,0xc2,0x01,len(boot),0,0xed,0xb0,0xc3,0,0xc2]
save('philips-scci-sector', [(0,entry),(0x40,boot),(0x100,accessory),(0x1fe,[0,0])])

# Issue #53: AB init runs without media. Position diskless, observe a no-input
# V=1 search after >1 s, cancel, paint white, then poll for an inserted disk.
# After insertion verify a no-step SEEK with a >=30 ms polling delay, read
# retained track 2 and export eight deterministic observations via sector 9.
q = Z80(0x4400)
def masked_record(address, register, expected, mask=255):
    load(register)
    if mask != 255: q.emit(0xe6, mask)
    store(address); check(expected)
def paint(color):
    for port_value in [color, 0x87, 0, 0x80, 0x40, 0x81]:
        q.emit(0x3e, port_value, 0xd3, 0x99)
def busy_poll(label):
    q.emit(0x11, 0xff, 0xff)
    q.label(label); load(0x7ff8); q.emit(0xcb, 0x47); q.jump(0xca, label+'_done')
    q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, label); q.jump(0xc3, 'fail')
    q.label(label+'_done')
masked_record(0x9000, 0x7ff8, 0x84, 0x95) # Reset A selection, motor off, zero.
value(0x7ffb, 2); value(0x7ff8, 0x10)
busy_poll('position')
masked_record(0x9001, 0x7ff9, 2)
masked_record(0x9002, 0x7ff8, 0x80, 0x95)
value(0x7ff8, 0x14)
masked_record(0x9003, 0x7ff8, 0x81, 0x91)
# 65535 * (DEC DE 6 + LD A,D 4 + OR E 4 + JP NZ 10 + four M1 waits)
# = 1,834,980 cycles per loop; three exceed one second (five revolutions).
for i in range(3):
    q.emit(0x11, 0xff, 0xff)
    q.label('no_input'+str(i)); q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'no_input'+str(i))
masked_record(0x9004, 0x7ff8, 0x81, 0x91)
value(0x7ff8, 0xd8)
masked_record(0x9005, 0x7fff, 0xbf)
masked_record(0x9006, 0x7ff8, 0x80, 0x91)
value(0x7ff8, 0xd0) # Status cannot acknowledge D8.
paint(0xff) # White checkpoint: browser/native host inserts media only now.
value(0x7ffd, 0x80)
q.label('insert'); load(0x7ff8); q.emit(0xcb, 0x7f); q.jump(0xc2, 'insert')
value(0x7ff8, 0x14) # Track/Data both 2, no movement, V=1.
q.emit(0x01, 0, 0)
q.label('verify'); q.emit(0x03); load(0x7fff); q.emit(0xcb, 0x77); q.jump(0xc2, 'verify')
# The 37 base cycles plus five ordinary MSX M1 waits give 42 cycles/loop.
# 30 ms settling + up to ceil(715909/9) ID cycles imply 2550..4455 polls,
# allowing a few instructions for command/start/final-sample alignment.
q.emit(0x60, 0x69, 0x11, 0xf6, 9, 0xb7, 0xed, 0x52); q.jump(0xda, 'fail')
q.emit(0x21, 0x67, 0x11, 0xb7, 0xed, 0x42); q.jump(0xda, 'fail')
masked_record(0x9007, 0x7ff8, 0, 0x91)
value(0x7ffa, 1); value(0x7ff8, 0x80)
q.emit(0x21, 0, 0x92, 0x01, 0, 2)
q.label('read_byte'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'read_byte')
q.label('read_data'); load(0x7ffb); check(0x62)
q.emit(0x77, 0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'read_byte')
wait_complete(q, 'complete'+str(len(q.code)))
load(0x7ff8); check(0, 0xfd)
q.emit(0x21, 0, 0x90, 0x11, 0, 0x92, 0x01, 8, 0, 0xed, 0xb0)
value(0x7ffa, 9); value(0x7ff8, 0xa0)
q.emit(0x21, 0, 0x92, 0x01, 0, 2)
q.label('write_byte'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'write_byte')
q.label('write_data'); q.emit(0x7e); store(0x7ffb)
q.emit(0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'write_byte')
wait_complete(q, 'complete'+str(len(q.code)))
load(0x7ff8); check(0, 0xfd)
value(0xc040, 0xa5); paint(0xf2); q.jump(0xc3, 'halt')
q.label('fail'); value(0xc040, 0xee); paint(0xf6)
q.label('halt'); q.emit(0x76); q.jump(0xc3, 'halt')
save('philips-readiness', [(0, [ord('A'), ord('B'), 0, 0x44]), (0x400, q.done())])

# Issue #57: CPU polls Type-II success and fifth-index failure with E=0/1.
# Original AB ROM, shared by native and compiled-Wasm tests. No BIOS shortcuts.
q = Z80(0x4400)
value(0x7ffd, 0x80); value(0x7ffc, 0); value(0x7ff9, 0)
for i, e in enumerate([0, 4]):
    trace = 0x9000 + 8*i
    value(0x7ffa, 3); value(0x7ff8, 0x80 | e)
    record(trace, 0x7ff8, 1)
    record(trace+1, 0x7fff, 0xff)
    q.emit(0x21, 0, 0x92, 0x01, 0, 0)
    poll = 'first'+str(i)
    q.label(poll); q.emit(0x03); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, poll)
    store(trace+2) # observed DRQ; preserve count and immediately consume byte 0
    load(0x7ffb); q.emit(0x77, 0x23, 0xc5, 0x01, 0xff, 1)
    q.label('byte'+str(i)); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'byte'+str(i))
    load(0x7ffb); check(0x62)
    q.emit(0x77, 0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'byte'+str(i))
    wait_complete(q, 'complete_read'+str(i))
    q.emit(0xc1)
    # 42 cycles/first poll. E*30 ms + one revolution + 46 byte times;
    # allow instruction alignment (and enforce E=1's >=30 ms delay).
    low, high = (2540, 19750) if e else (0, 17190)
    q.emit(0x60, 0x69, 0x11, low & 255, low >> 8, 0xb7, 0xed, 0x52); q.jump(0xda, 'fail')
    q.emit(0x21, high & 255, high >> 8, 0xb7, 0xed, 0x42); q.jump(0xda, 'fail')
    load(trace+2); check(0x7f)
    record(trace+3, 0x7ff8, 0)
    # Verify every payload byte, including the first one, after the timed read.
    q.emit(0x21, 0, 0x92, 0x01, 0, 2)
    q.label('verify_read'+str(i)); q.emit(0x7e); check(0x62)
    q.emit(0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'verify_read'+str(i))
    value(0x7ffa, 10); value(0x7ff8, 0x80 | e)
    record(trace+4, 0x7ff8, 1)
    record(trace+5, 0x7fff, 0xff)
    q.emit(0x01, 0, 0)
    poll = 'missing'+str(i)
    q.label(poll); q.emit(0x03, 0, 0, 0, 0); load(0x7fff)
    q.emit(0xcb, 0x77); q.jump(0xc2, poll)
    # 62 cycles/poll: E=0/1 failure lies within four revolutions ..
    # 30 ms + five revolutions (2863636 .. 3686931.35 cycles).
    # 46000..59500 includes alignment and fits a 16-bit counter.
    q.emit(0x60, 0x69, 0x11, 0xb0, 0xb3, 0xb7, 0xed, 0x52); q.jump(0xda, 'fail')
    q.emit(0x21, 0x6c, 0xe8, 0xb7, 0xed, 0x42); q.jump(0xda, 'fail')
    record(trace+6, 0x7fff, 0xbf)
    record(trace+7, 0x7ff8, 0x10)
# Replace the first sixteen known payload bytes with the fixed observation trace.
q.emit(0x21, 0, 0x90, 0x11, 0, 0x92, 0x01, 16, 0, 0xed, 0xb0)
load(0x43ff); store(0x7ffc) # test supplies side 0/1 for 360/720 KiB
value(0x7ffa, 9); value(0x7ff8, 0xa4)
q.emit(0x21, 0, 0x92, 0x01, 0, 2)
q.label('write'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xc2, 'write')
q.emit(0x7e); store(0x7ffb)
q.emit(0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'write')
wait_complete(q, 'complete_write')
load(0x7ff8); check(0)
value(0xc050, 0xa5); paint(0xf2); q.jump(0xc3, 'halt')
q.label('fail'); value(0xc050, 0xee); paint(0xf6)
q.label('halt'); q.emit(0x76); q.jump(0xc3, 'halt')
save('philips-search', [(0, [ord('A'), ord('B'), 0, 0x44]), (0x3ff, [0]), (0x400, q.done())])

# Issue #59: CPU-visible overrun, clean full read, initial write starvation,
# later write zero-fill and a full trace/payload export through both buses.
# Each wait allows 65535 polls (>2M cycles), above rev + 559 byte times
# (779940 cycles). Inner serviced-byte paths are <114 cycles with MSX waits.
def clock_probe(base, philips):
    c = Z80(base)
    def ld(address): c.emit(0x3a, address & 255, address >> 8)
    def st(address): c.emit(0x32, address & 255, address >> 8)
    def val(address, byte): c.emit(0x3e, byte); st(address)
    def ck(byte): c.emit(0xfe, byte); c.jump(0xc2, 'fail')
    def command(sector, byte): val(0x7ffa, sector); val(0x7ff8, byte)
    def poll(label, drq=False):
        mask = (0x80 if drq else 0x40) if philips else (0x40 if drq else 0x80)
        c.emit(0x11, 0xff, 0xff)
        c.label(label); ld(0x7fff); c.emit(0xe6, mask)
        c.jump(0xca if philips else 0xc2, label+'_done')
        c.emit(0x1b, 0x7a, 0xb3); c.jump(0xc2, label); c.jump(0xc3, 'fail')
        c.label(label+'_done')
    def status(trace, byte): ld(0x7ff8); st(0x9000+trace); ck(byte)
    val(0x7ffd, 0x80 if philips else 0x81); val(0x7ffc, 0); val(0x7ff9, 0)
    command(3, 0x80)
    poll('overrun') # Deliberately read none of the 512 arrivals.
    ld(0x7fff); st(0x9000); ck(0xbf if philips else 0x80)
    status(1, 4)
    ld(0x7ffb); st(0x9002); ck(0xb8) # last independent pattern byte
    ld(0x7ffb); ck(0xb8) # repeated/idle accesses retain the last register
    command(3, 0x80)
    c.emit(0x21, 0, 0x92, 0x01, 0, 2)
    c.label('read'); ld(0x7fff); c.emit(0xe6, 0x80 if philips else 0x40)
    c.jump(0xc2 if philips else 0xca, 'read')
    ld(0x7ffb); c.emit(0x77, 0x23, 0x0b, 0x78, 0xb1); c.jump(0xc2, 'read')
    wait_complete(c, 'read_complete'); status(3, 0)
    # Independently verify both 256-byte halves, not just a checksum or marker.
    c.emit(0x21, 0, 0x92)
    for half in range(2):
        c.emit(0x06, 0, 0x16, half)
        c.label('verify'+str(half)); c.emit(0x7e, 0xba); c.jump(0xc2, 'fail')
        c.emit(0x23, 0x7a, 0xc6, 73, 0x57, 0x05); c.jump(0xc2, 'verify'+str(half))
    command(5, 0xa0)
    poll('starve'); status(4, 4) # No first byte: no media change.
    command(6, 0xa0)
    poll('first_write', True); val(0x7ffb, 0x61)
    poll('underrun'); status(5, 4) # Starts writing: all later positions become zero.
    c.emit(0x21, 0, 0x90, 0x11, 0, 0x92, 0x01, 6, 0, 0xed, 0xb0)
    command(9, 0xa0)
    c.emit(0x21, 0, 0x92, 0x01, 0, 2)
    c.label('write'); ld(0x7fff); c.emit(0xe6, 0x80 if philips else 0x40)
    c.jump(0xc2 if philips else 0xca, 'write')
    c.emit(0x7e); st(0x7ffb)
    c.emit(0x23, 0x0b, 0x78, 0xb1); c.jump(0xc2, 'write')
    wait_complete(c, 'write_complete'); ld(0x7ff8); ck(0)
    val(0xc060, 0xa5); c.emit(0x3e, 0xf2); c.jump(0xc3, 'paint')
    c.label('fail'); val(0xc060, 0xee); c.emit(0x3e, 0xf6)
    c.label('paint'); c.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
        0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
        0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
    c.label('halt'); c.emit(0x76); c.jump(0xc3, 'halt')
    return c.done()

save('philips-clock', [(0, [ord('A'), ord('B'), 0, 0x44]), (0x400, clock_probe(0x4400, True))])
# A real Weave boot sector loads two sectors via DISKIO then executes the same
# diagnostic through its opposite-polarity interface. F8/F9 is patched by tests.
loader = [0xaf, 0x01, 0xf8, 2, 0x11, 1, 0, 0x21, 0, 0xc2, 0xb7,
          0xcd, 0x10, 0x40, 0xc3, 0, 0xc2]
weave_clock = clock_probe(0xc200, False)
assert len(weave_clock) <= 512
save('philips-clock-weave', [(0, loader), (510, list(b'WV')), (512, weave_clock)])

# Issue #61: original Type-IV register trace. No production helpers/oracles.
# The CPU checks each byte before saving the trace to sector 9; all other bytes
# must survive, including an explicitly canceled initial write to sector 6.
def force_probe(base, philips):
    c = Z80(base)
    trace = 0
    def ld(address): c.emit(0x3a, address & 255, address >> 8)
    def st(address): c.emit(0x32, address & 255, address >> 8)
    def val(address, byte): c.emit(0x3e, byte); st(address)
    def cmd(byte): val(0x7ff8, byte)
    def record(register, expected, mask=255):
        nonlocal trace
        ld(register)
        if mask != 255: c.emit(0xe6, mask)
        st(0x9000+trace); c.emit(0xfe, expected); c.jump(0xc2, 'fail')
        trace += 1
    def signal(active): record(0x7fff, (0xbf if active else 0xff) if philips else (0x80 if active else 0))
    def status(byte, type_one=False): record(0x7ff8, byte, 0xfd if type_one else 255)
    def poll(label, drq=False):
        mask = (0x80 if drq else 0x40) if philips else (0x40 if drq else 0x80)
        c.emit(0x11, 0xff, 0xff)
        c.label(label); ld(0x7fff); c.emit(0xe6, mask)
        c.jump(0xca if philips else 0xc2, label+'_done')
        c.emit(0x1b, 0x7a, 0xb3); c.jump(0xc2, label); c.jump(0xc3, 'fail')
        c.label(label+'_done')
    val(0x7ffd, 0x80 if philips else 0x81); val(0x7ffc, 0); val(0x7ff9, 0)
    # Fill the complete export sector before recording independently checked bytes.
    val(0x9000, 0x35)
    c.emit(0x21, 0, 0x90, 0x11, 1, 0x90, 0x01, 0xff, 1, 0xed, 0xb0)
    val(0x7ffa, 3); cmd(0x80); poll('arrival', True)
    c.emit(0x06, 0); c.label('overrun'); c.emit(0x10, 0xfe) # 256 DJNZ, >30 bytes
    status(7)
    cmd(0xd8); status(4); signal(True); status(4); signal(True)
    cmd(0x80); status(1); signal(True) # accepted ordinary command keeps D8
    cmd(0xd1); status(0); signal(True) # another nonzero Type IV keeps D8
    cmd(0xd0); status(4, True); signal(False)
    cmd(0xd8); signal(True); cmd(0xd0); status(4, True); signal(False)
    cmd(0xd8); cmd(0xd0); cmd(0x80); signal(False); cmd(0xd0); status(0)
    cmd(0xd7); signal(False)
    val(0x7ffd, 0 if philips else 1); signal(True); status(0x84, True); signal(False)
    val(0x7ffd, 0 if philips else 1); signal(False) # unchanged READY
    val(0x7ffd, 0x80 if philips else 0x81); signal(True); status(4, True); signal(False)
    poll('index1'); signal(True); status(4, True); signal(False)
    poll('index2'); signal(True); status(4, True); signal(False)
    cmd(0x00); status(4, True); signal(False) # ordinary completion, disarms D7
    val(0x7ffd, 0 if philips else 1); signal(False)
    val(0x7ffd, 0x80 if philips else 0x81); signal(False)
    # >one revolution; disarmed index events cannot resurrect IRQ.
    c.emit(0x11, 0xff, 0xff)
    c.label('elapsed'); c.emit(0x1b, 0x7a, 0xb3); c.jump(0xc2, 'elapsed')
    signal(False)
    val(0x7ffa, 6); cmd(0xa0); poll('partial', True); val(0x7ffb, 0x61)
    cmd(0xd0); status(0); signal(False)
    val(0x7ffa, 9); cmd(0xa0)
    c.emit(0x21, 0, 0x90, 0x01, 0, 2)
    c.label('write'); ld(0x7fff); c.emit(0xe6, 0x80 if philips else 0x40)
    c.jump(0xc2 if philips else 0xca, 'write')
    c.emit(0x7e); st(0x7ffb)
    c.emit(0x23, 0x0b, 0x78, 0xb1); c.jump(0xc2, 'write')
    wait_complete(c, 'complete'); status(0)
    val(0xc061, 0xa5); c.emit(0x3e, 0xf2); c.jump(0xc3, 'paint')
    c.label('fail'); val(0xc061, 0xee); c.emit(0x3e, 0xf6)
    c.label('paint'); c.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
        0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
        0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
    c.label('halt'); c.emit(0x76); c.jump(0xc3, 'halt')
    return c.done()

save('philips-force', [(0, [ord('A'), ord('B'), 0, 0x44]), (0x400, force_probe(0x4400, True))])
force_loader = loader.copy(); force_loader[3] = 3 # load three sectors of code
weave_force = force_probe(0xc200, False)
assert len(weave_force) <= 1536
save('philips-force-weave', [(0, force_loader), (510, list(b'WV')), (512, weave_force)])

# Issue #69: original Read Address trace. Align to a real index IRQ, then
# inspect ID 2, starve ID 3, recover with E=1 at ID 5, seek cylinder 2 and
# inspect ID 2 on the recorded side. Every byte/CRC is checked by Z80 code.
# The side parameter is ROM file offset 03FF (Philips), boot offset 01FD (Weave).
def address_probe(base, philips):
    c = Z80(base)
    trace = 0
    def ld(address): c.emit(0x3a, address & 255, address >> 8)
    def st(address): c.emit(0x32, address & 255, address >> 8)
    def val(address, byte): c.emit(0x3e, byte); st(address)
    def ck(byte): c.emit(0xfe, byte); c.jump(0xc2, 'fail')
    def cmd(byte): val(0x7ff8, byte)
    def record(register, byte):
        nonlocal trace
        ld(register); st(0x9000+trace); ck(byte); trace += 1
    def poll(label):
        c.emit(0x11, 0xff, 0xff)
        c.label(label); ld(0x7fff); c.emit(0xe6, 0x40 if philips else 0x80)
        c.jump(0xca if philips else 0xc2, label+'_done')
        c.emit(0x1b, 0x7a, 0xb3); c.jump(0xc2, label); c.jump(0xc3, 'fail')
        c.label(label+'_done')
    def align(label):
        cmd(0xd4); poll(label); cmd(0xd0)
    def read_id(label, command, expected, sided=False):
        nonlocal trace
        cmd(command)
        c.emit(0x21, trace, 0x90, 0x06, 6)
        # Bounded initial wait, then <114-cycle per-byte servicing, real registers.
        c.emit(0x11, 0xff, 0xff)
        c.label(label); ld(0x7fff); c.emit(0xe6, 0x80 if philips else 0x40)
        c.jump(0xca if philips else 0xc2, label+'_data')
        c.emit(0x1b, 0x7a, 0xb3); c.jump(0xc2, label); c.jump(0xc3, 'fail')
        c.label(label+'_data'); ld(0x7ffb); c.emit(0x77, 0x23, 0x05); c.jump(0xc2, label)
        poll(label+'_complete')
        if sided:
            ld(0x9200); c.emit(0xb7); c.jump(0xca, label+'_side0')
            for i, byte in enumerate([2,1,2,2,0x45,0x64]):
                ld(0x9000+trace+i); ck(byte)
            c.jump(0xc3, label+'_checked'); c.label(label+'_side0')
        for i, byte in enumerate(expected):
            ld(0x9000+trace+i); ck(byte)
        if sided: c.label(label+'_checked')
        trace += 6
    val(0x7ffd, 0x80 if philips else 0x81); val(0x7ffc, 0)
    val(0x9000, 0x35)
    c.emit(0x21, 0, 0x90, 0x11, 1, 0x90, 0x01, 0xff, 1, 0xed, 0xb0)
    val(0x7ff9, 123); val(0x7ffa, 255)
    align('index0')
    read_id('first', 0xc0, [0,0,2,2,0x9f,0x3c])
    record(0x7fff, 0xbf if philips else 0x80)
    record(0x7ff8, 0); record(0x7fff, 0xff if philips else 0)
    cmd(0xc0); poll('starve'); record(0x7ff8, 4); record(0x7ffb, 0x0d)
    read_id('recovery', 0xc4, [0,0,5,2,0x06,0xab]); record(0x7ff8, 0)
    # Repair only Track before SEEK; physical cylinder is still zero.
    val(0x7ff9, 0); val(0x7ffb, 2); cmd(0x10); poll('seek')
    ld(0x43ff if philips else 0xc1fd); st(0x9200); st(0x7ffc)
    val(0x7ff9, 123); val(0x7ffa, 255)
    align('index2')
    read_id('cylinder', 0xc0, [2,0,2,2,0x72,0x54], True)
    record(0x7ff8, 0); record(0x7ff9, 123); record(0x7ffa, 2)
    assert trace == 27
    # Export all observations using a normal sector write on cylinder 2, side 0.
    val(0x7ff9, 2); val(0x7ffc, 0); val(0x7ffa, 9); cmd(0xa0)
    c.emit(0x21, 0, 0x90, 0x01, 0, 2)
    c.label('write'); ld(0x7fff); c.emit(0xe6, 0x80 if philips else 0x40)
    c.jump(0xc2 if philips else 0xca, 'write')
    c.emit(0x7e); st(0x7ffb); c.emit(0x23, 0x0b, 0x78, 0xb1); c.jump(0xc2, 'write')
    wait_complete(c, 'complete'); ld(0x7ff8); ck(0)
    val(0xc069, 0xa5); c.emit(0x3e, 0xf2); c.jump(0xc3, 'paint')
    c.label('fail'); val(0xc069, 0xee); c.emit(0x3e, 0xf6)
    c.label('paint'); c.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
        0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
        0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
    c.label('halt'); c.emit(0x76); c.jump(0xc3, 'halt')
    return c.done()

save('philips-address', [(0, [ord('A'), ord('B'), 0, 0x44]), (0x3ff, [0]), (0x400, address_probe(0x4400, True))])
address_loader = loader.copy(); address_loader[3] = 3
weave_address = address_probe(0xc200, False)
assert len(weave_address) <= 1536
save('philips-address-weave', [(0, address_loader), (509, [0]), (510, list(b'WV')), (512, weave_address)])
